#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

#
# Issue #36 (0verlabs/herald): provision Herald's NEAR relayer for one Herald
# environment. The relayer pays the gas of every NEAR settlement, Receiving
# Address setup and NEAR Sweep, sent from the facilitator's NearChainQueue.
# Run it once per environment, from anywhere in the repo:
#
#   scripts/near-relayer-wizard.sh testnet      # Herald testnet, NEAR testnet
#   scripts/near-relayer-wizard.sh production   # Herald mainnet: spends real NEAR
#
# The relayer is a NEAR implicit account: its account id is the lowercase hex
# of its ed25519 public key, so the key alone names the account. The wizard
# generates the key locally, funds the account (the first transfer creates it,
# with that key as its full-access key) and stores the key as the
# facilitator's NEAR_RELAYER_KEY Worker secret, in near-cli format:
#
#   ed25519:<base58 of the 64-byte secret key: 32-byte seed, then public key>
#
# which near-api-js `KeyPair.fromString` parses. The private key is written
# only to ~/.near-credentials/<network>/<account id>.json (mode 0600: the
# legacy near-cli keychain, so `near ... sign-with-legacy-keychain` can use
# it) and reaches Wrangler on stdin. It is never printed, never passed as a
# command argument, and never written inside the repo.
#
# Public values (relayer account ids, the testnet faucet account) persist in
# .env.near-relayer (gitignored), so a re-run reuses the relayer it made.
# Nothing goes to GitHub secrets.

REPO="0verlabs/herald"
ISSUE=36
FACILITATOR_DIR="apps/facilitator"
CREDENTIALS_DIR="$HOME/.near-credentials"
TICK="${GREEN}✓${RESET}"

# Set by the "Environment and tools" stage.
TARGET=""        # Cloudflare environment: testnet | production
NEAR_NETWORK=""  # testnet | mainnet
WORKER=""        # the facilitator Worker of that environment
ACCOUNT_KEY=""   # .env.near-relayer key holding the relayer's account id
EXPLORER=""      # nearblocks base URL

RELAYER=""
RELAYER_PUBLIC_KEY=""
FUNDED_NOTE="not funded by this run"
SECRET_SET=""
MAINNET_CONFIRMATION=""

has() { command -v "$1" >/dev/null 2>&1; }

# wrangler ARGS...: the facilitator's own Wrangler, aimed at the chosen
# environment the way the repo's README does it (CLOUDFLARE_ENV).
wrangler() {
  (cd "$FACILITATOR_DIR" && CLOUDFLARE_ENV="$TARGET" ./node_modules/.bin/wrangler "$@")
}

# key_file ACCOUNT: where the relayer's key file lives on this machine.
key_file() { printf '%s/%s/%s.json' "$CREDENTIALS_DIR" "$NEAR_NETWORK" "$1"; }

# generate_key: makes a fresh ed25519 key, saves it as a near-cli key file
# (refusing to overwrite one) and prints only its implicit account id.
generate_key() {
  node -e '
    const { generateKeyPairSync } = require("node:crypto");
    const fs = require("node:fs");
    const path = require("node:path");
    const dir = process.argv[1];
    const { publicKey, privateKey } = generateKeyPairSync("ed25519");
    const pub = Buffer.from(publicKey.export({ format: "jwk" }).x, "base64url");
    const seed = Buffer.from(privateKey.export({ format: "jwk" }).d, "base64url");
    const alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
    const base58 = (bytes) => {
      let n = BigInt("0x" + bytes.toString("hex"));
      let out = "";
      while (n > 0n) { out = alphabet[Number(n % 58n)] + out; n /= 58n; }
      for (const b of bytes) { if (b !== 0) break; out = "1" + out; }
      return out;
    };
    const accountId = pub.toString("hex");
    fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
    fs.writeFileSync(
      path.join(dir, accountId + ".json"),
      JSON.stringify({
        account_id: accountId,
        public_key: "ed25519:" + base58(pub),
        private_key: "ed25519:" + base58(Buffer.concat([seed, pub])),
      }) + "\n",
      { mode: 0o600, flag: "wx" },
    );
    process.stdout.write(accountId);
  ' "$CREDENTIALS_DIR/$NEAR_NETWORK"
}

# public_key_of FILE: the public key of a key file (safe to show).
public_key_of() {
  node -e 'process.stdout.write(JSON.parse(require("fs").readFileSync(process.argv[1], "utf8")).public_key)' "$1"
}

# private_key_of FILE: the private key of a key file, on stdout. Only ever
# pipe it straight into the command that needs it.
private_key_of() {
  node -e 'process.stdout.write(JSON.parse(require("fs").readFileSync(process.argv[1], "utf8")).private_key)' "$1"
}

# account_exists ACCOUNT: the account is live on the environment's network.
account_exists() {
  near account view-account-summary "$1" network-config "$NEAR_NETWORK" now >/dev/null 2>&1
}

show_balance() {
  near tokens "$1" view-near-balance network-config "$NEAR_NETWORK" now 2>&1 | sed 's/^/    /' || true
}

# ask_amount DEFAULT "Prompt": reads a NEAR amount into AMOUNT.
ask_amount() {
  AMOUNT=""
  while :; do
    printf '  %s%s%s ' "$BOLD" "$2" "$RESET"
    read -r AMOUNT || exit 1
    AMOUNT="${AMOUNT:-$1}"
    [[ "$AMOUNT" =~ ^[0-9]+(\.[0-9]+)?$ ]] && return 0
    warn "enter a plain number of NEAR, like 2 or 0.5"
  done
}

fund_by_web_faucet() {
  say "Use the web faucet instead: it sends testnet NEAR straight to an account id."
  open_url "https://docs.near.org/getting-started/faucet"
  step "Paste the relayer account id as the Testnet Account ID, then click Request:"
  say "    $RELAYER"
  note "If it refuses a 64-character implicit id, try https://near-faucet.io/ with the same id."
  pause "Press Enter once the faucet says it sent the NEAR."
  FUNDED_NOTE="funded from the testnet web faucet"
}

fund_testnet() {
  local default_funder
  say "Testnet NEAR comes from the faucet. The near CLI faucet only creates named"
  say ".testnet accounts, so the wizard creates a throwaway faucet account and"
  say "sends its NEAR on to the relayer. Its key goes to your OS keychain."
  default_funder="herald-relayer-funder-$(date +%s).testnet"
  ask NEAR_FAUCET_ACCOUNT_TESTNET "Faucet account to create or reuse (Enter for $default_funder):"
  write_env NEAR_FAUCET_ACCOUNT_TESTNET "${NEAR_FAUCET_ACCOUNT_TESTNET:-$default_funder}"
  local funder="$NEAR_FAUCET_ACCOUNT_TESTNET"

  if ! account_exists "$funder"; then
    step "Creating $funder from the faucet…"
    if ! near account create-account sponsor-by-faucet-service "$funder" \
        autogenerate-new-keypair save-to-keychain network-config testnet create; then
      warn "The near CLI faucet failed."
      fund_by_web_faucet
      return
    fi
  fi
  say "Faucet account balance:"
  show_balance "$funder"
  ask_amount 9 "How much NEAR to send to the relayer? (Enter for 9; leave some for gas)"
  if near tokens "$funder" send-near "$RELAYER" "$AMOUNT NEAR" \
      network-config testnet sign-with-keychain send; then
    FUNDED_NOTE="funded with $AMOUNT testnet NEAR from faucet account \`$funder\`"
  else
    warn "The transfer from $funder failed."
    fund_by_web_faucet
  fi
}

fund_mainnet() {
  local typed funder
  warn "Herald mainnet: this spends real NEAR."
  say "Herald's fee-wallet view warns below 0.5 NEAR. Each Provider's Receiving"
  say "Address setup costs about 0.003 NEAR plus gas, and every settlement and"
  say "NEAR Sweep pays gas from the relayer."
  ask_amount 2 "How much NEAR to send to the relayer? (Enter for 2)"
  say ""
  say "Relayer: $RELAYER"
  printf '  %sTo spend %s real NEAR, type exactly:%s send %s NEAR\n  > ' "$YELLOW" "$AMOUNT" "$RESET" "$AMOUNT"
  read -r typed || exit 1
  if [[ "$typed" != "send $AMOUNT NEAR" ]]; then
    say "Not confirmed. Nothing was sent. Re-run to fund it: the relayer key is kept."
    exit 0
  fi
  MAINNET_CONFIRMATION="typed \"$typed\" at $(date -u +%Y-%m-%dT%H:%M:%SZ)"

  if confirm "Send it with the near CLI from a mainnet account in your keychain? (No: from your own wallet)"; then
    ask NEAR_FUNDER_ACCOUNT_MAINNET "Your mainnet account to send from:"
    write_env NEAR_FUNDER_ACCOUNT_MAINNET "$NEAR_FUNDER_ACCOUNT_MAINNET"
    funder="$NEAR_FUNDER_ACCOUNT_MAINNET"
    if near tokens "$funder" send-near "$RELAYER" "$AMOUNT NEAR" \
        network-config mainnet sign-with-keychain send; then
      FUNDED_NOTE="funded with $AMOUNT NEAR from \`$funder\`"
      return
    fi
    warn "The near CLI transfer failed. Send it from your wallet instead."
  fi
  step "In your NEAR wallet, send $AMOUNT NEAR to the relayer (a 64-character implicit account):"
  say "    $RELAYER"
  note "Check the first and last 6 characters before you send."
  pause "Press Enter once the transfer has confirmed."
  FUNDED_NOTE="funded with $AMOUNT NEAR from the operator's wallet"
}

run_wizard() {

TOTAL_STAGES=7

cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE=".env.near-relayer"

banner "Herald NEAR relayer"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Environment and tools"
case "${1:-}" in
  testnet|production) TARGET="$1" ;;
  "") ;;
  *) warn "unknown environment '$1': use testnet or production" ;;
esac
while [[ "$TARGET" != testnet && "$TARGET" != production ]]; do
  printf '  %sWhich Herald environment? [testnet/production]%s ' "$BOLD" "$RESET"
  read -r TARGET || exit 1
done
if [[ "$TARGET" == testnet ]]; then
  NEAR_NETWORK=testnet; WORKER=herald-facilitator-testnet
  ACCOUNT_KEY=NEAR_RELAYER_ACCOUNT_TESTNET; EXPLORER="https://testnet.nearblocks.io"
else
  NEAR_NETWORK=mainnet; WORKER=herald-facilitator-mainnet
  ACCOUNT_KEY=NEAR_RELAYER_ACCOUNT_MAINNET; EXPLORER="https://nearblocks.io"
fi
say "Herald $TARGET: NEAR $NEAR_NETWORK, facilitator Worker $WORKER."

if [[ "$TARGET" == production ]]; then
  warn "This provisions the mainnet relayer. Funding it spends real NEAR, and"
  warn "setting its secret deploys a new version of $WORKER."
  printf '  %sType mainnet to continue:%s ' "$YELLOW" "$RESET"
  read -r typed || exit 1
  if [[ "$typed" != mainnet ]]; then say "Stopped. Nothing was created or spent."; exit 0; fi
fi

has node || { warn "node is missing: install the Node version the repo needs (>= 22.18)."; exit 1; }
until has near; do
  warn "The near CLI (near-cli-rs) is missing. Install it with one of:"
  say "    npm install -g near-cli-rs"
  say "    curl --proto '=https' --tlsv1.2 -LsSf https://github.com/near/near-cli-rs/releases/latest/download/near-cli-rs-installer.sh | sh"
  pause "Press Enter once \`near --version\` works."
done
note "near CLI: $(near --version 2>/dev/null || echo unknown)"
until [[ -x "$FACILITATOR_DIR/node_modules/.bin/wrangler" ]]; do
  warn "The facilitator's Wrangler isn't installed. Run \`vp install\` at the repo root."
  pause "Press Enter once it finished."
done
until whoami_out=$(wrangler whoami 2>&1) && [[ "$whoami_out" != *"not authenticated"* ]]; do
  warn "Wrangler isn't logged in to Cloudflare. In another terminal run:"
  say "    cd $FACILITATOR_DIR && npx wrangler login"
  pause "Press Enter once you're logged in."
done
printf '%s\n' "$whoami_out" | sed 's/^/    /'
confirm "Is this the Cloudflare account that runs $WORKER?" \
  || { say "Log in to the right account (npx wrangler login), then re-run."; exit 1; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Relayer key"
RELAYER=$(_existing "$ACCOUNT_KEY" || true)
if [[ -n "$RELAYER" && -f "$(key_file "$RELAYER")" ]]; then
  say "Reusing the NEAR $NEAR_NETWORK relayer this wizard made before."
elif [[ -n "$RELAYER" ]]; then
  warn "No key file on this machine for the saved relayer $RELAYER:"
  note "  expected $(key_file "$RELAYER")"
  confirm "Make a new relayer instead?" \
    || { say "Restore that key file, then re-run."; exit 1; }
  RELAYER=""
fi
if [[ -z "$RELAYER" ]]; then
  RELAYER=$(generate_key)
  write_env "$ACCOUNT_KEY" "$RELAYER"
  say "$TICK Generated a new ed25519 key for the relayer."
fi
RELAYER_PUBLIC_KEY=$(public_key_of "$(key_file "$RELAYER")")
say ""
say "Relayer account:  $RELAYER"
say "Full-access key:  $RELAYER_PUBLIC_KEY"
note "Private key: only in $(key_file "$RELAYER") (mode 0600), never shown."
say ""
warn "The relayer must never be a Buyer's account. Don't use this key in the"
warn "example buyer or any wallet that pays Herald Providers: stock @x402/near"
warn "refuses a payment whose Buyer is the relayer."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Fund the relayer"
skip_funding=""
if account_exists "$RELAYER"; then
  say "The relayer account already exists on NEAR $NEAR_NETWORK. Balance:"
  show_balance "$RELAYER"
  if ! confirm "Send it more NEAR?"; then skip_funding=1; FUNDED_NOTE="already funded, no NEAR sent this run"; fi
fi
if [[ -z "$skip_funding" ]]; then
  say "The first transfer creates the account, with the relayer key as its"
  say "full-access key. Until then the account doesn't exist on chain."
  say ""
  if [[ "$NEAR_NETWORK" == testnet ]]; then fund_testnet; else fund_mainnet; fi
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Check the relayer on chain"
until account_exists "$RELAYER"; do
  warn "NEAR $NEAR_NETWORK doesn't show $RELAYER yet."
  confirm "Check again?" \
    || { say "Fund it, then re-run: the wizard reuses this relayer."; exit 1; }
done
keys_out=$(near account list-keys "$RELAYER" network-config "$NEAR_NETWORK" now 2>&1 || true)
if [[ "$keys_out" == *"$RELAYER_PUBLIC_KEY"* ]]; then
  say "$TICK $RELAYER exists and holds the relayer key."
else
  warn "The relayer key isn't among the account's access keys:"
  printf '%s\n' "$keys_out" | sed 's/^/    /'
  confirm "Continue anyway?" || exit 1
fi
say "Balance:"
show_balance "$RELAYER"
open_url "$EXPLORER/address/$RELAYER"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Store NEAR_RELAYER_KEY on the facilitator"
say "The key goes to $WORKER as the NEAR_RELAYER_KEY Worker secret, piped"
say "from the key file. Only the facilitator needs it: its NearChainQueue holds"
say "the key, and the web Worker reaches the relayer through that queue."
say "Format: ed25519:<base58 of the 64-byte secret key>."
warn "wrangler secret put deploys a new version of $WORKER right away."
if confirm "Set NEAR_RELAYER_KEY on $WORKER now?"; then
  if private_key_of "$(key_file "$RELAYER")" | wrangler secret put NEAR_RELAYER_KEY; then
    SECRET_SET=1
    if [[ "$(wrangler secret list 2>&1 || true)" == *NEAR_RELAYER_KEY* ]]; then
      say "$TICK $WORKER lists NEAR_RELAYER_KEY."
    else
      warn "wrangler secret list doesn't show NEAR_RELAYER_KEY yet; check the dashboard."
    fi
  else
    warn "wrangler secret put failed."
  fi
fi
[[ -n "$SECRET_SET" ]] \
  || SKIPPED+=("NEAR_RELAYER_KEY on $WORKER: re-run this wizard (it reuses the relayer)")
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Back up the key"
say "Cloudflare secrets can't be read back, so this file is the only readable"
say "copy of the relayer key:"
say "    $(key_file "$RELAYER")"
step "Store it in the team's password manager or vault."
note "It's also a legacy near-cli keychain entry, so near CLI commands with"
note "sign-with-legacy-keychain can sign as the relayer (to rotate its key, say)."
warn "Never commit it, paste it into chat or an issue, or use it as a Buyer key."
pause "Press Enter once it's backed up."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Record it on #$ISSUE"
secret_line="not set yet"
[[ -n "$SECRET_SET" ]] && secret_line="set on \`$WORKER\`"
comment="NEAR relayer for Herald $TARGET, provisioned with \`scripts/near-relayer-wizard.sh\`.

- Relayer (implicit account): [\`$RELAYER\`]($EXPLORER/address/$RELAYER)
- Full-access public key: \`$RELAYER_PUBLIC_KEY\`
- Funding: $FUNDED_NOTE
- \`NEAR_RELAYER_KEY\`: $secret_line"
[[ -n "$MAINNET_CONFIRMATION" ]] \
  && comment+=$'\n'"- Mainnet spend confirmed by the operator: $MAINNET_CONFIRMATION"
say "This comment holds public values only, never the key:"
say ""
printf '%s\n' "$comment" | sed 's/^/    /'
say ""
if has gh && gh auth status >/dev/null 2>&1; then
  if confirm "Post it on $REPO#$ISSUE?"; then
    if gh issue comment "$ISSUE" --repo "$REPO" --body "$comment" >/dev/null; then
      say "$TICK Posted on #$ISSUE."
    else
      SKIPPED+=("comment on $REPO#$ISSUE (gh issue comment failed)")
    fi
  else
    SKIPPED+=("comment on $REPO#$ISSUE with the relayer account and funding")
  fi
else
  warn "gh isn't ready, so post that comment on #$ISSUE by hand."
  SKIPPED+=("comment on $REPO#$ISSUE with the relayer account and funding")
fi

finish
note "Herald $TARGET relayer: $RELAYER"
[[ -n "$SECRET_SET" ]] && note "NEAR_RELAYER_KEY set on $WORKER"
note "Key file: $(key_file "$RELAYER")"
printf '\n'
}

run_wizard "$@"; exit
